  ground:new THREE.MeshStandardMaterial({color:'#394341',roughness:1}),
  asphalt:new THREE.MeshStandardMaterial({color:'#222d2f',roughness:.94}),
  concrete:new THREE.MeshStandardMaterial({color:'#66716b',roughness:.92}),
  dark:new THREE.MeshStandardMaterial({color:'#162124',roughness:.8}),
  rust:new THREE.MeshStandardMaterial({color:'#815b49',roughness:.9}),
  glass:new THREE.MeshStandardMaterial({color:'#526d69',roughness:.28,metalness:.25}),
