import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
const errors = [];
page.on('pageerror', e => errors.push('PAGEERROR: ' + e.message));
page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE: ' + m.text()); });
await page.goto('http://localhost:3002/', { waitUntil: 'load', timeout: 45000 });
await page.waitForTimeout(1500);
await page.locator('#start-button').click();
await page.waitForTimeout(1200);

async function teleport(x, z) {
  await page.evaluate(([x, z]) => window.__dbg.teleport(x, z), [x, z]);
  await page.waitForTimeout(350);
}
async function shot(name) { await page.screenshot({ path: `/tmp/opencode/${name}.png` }); }
async function pressE() { await page.keyboard.press('KeyE'); await page.waitForTimeout(300); }
async function clickTone(slot, times) {
  for (let i = 0; i < times; i++) await page.locator(`#tone-row [data-slot="${slot}"]`).click();
}

// Archive interior + puzzle.
await teleport(-27, 10);
await shot('archive-interior');
const nearArchive = await page.evaluate(() => !!window.__dbg.nearby);
await page.evaluate(() => window.__dbg.openPuzzle(window.__dbg.archive));
await page.waitForTimeout(250);
await clickTone(0, 2); await clickTone(1, 1); await clickTone(2, 4);
await page.locator('#puzzle-submit').click();
await page.waitForTimeout(400);
let s = await page.evaluate(() => ({ pass: window.__dbg.pass, obj: window.__dbg.objectiveIndex, near: !!window.__dbg.nearby }));
console.log('archive', { nearArchive, ...s });

// Relay 1.
await teleport(-12, 41);
await pressE();
await page.waitForTimeout(250);
await clickTone(0, 1); await clickTone(1, 3); await clickTone(2, 4);
await page.locator('#puzzle-submit').click();
await page.waitForTimeout(500);
s = await page.evaluate(() => ({ obj: window.__dbg.objectiveIndex, chapter: document.querySelector('#chapter-label').textContent, solved: [...window.__dbg.solved] }));
console.log('relay1', s);

// Checkpoint.
await teleport(4.8, 10);
await pressE();
await page.waitForTimeout(500);
s = await page.evaluate(() => ({ obj: window.__dbg.objectiveIndex, banner: document.querySelector('#chapter-banner').className }));
console.log('checkpoint', s);
await shot('middle-tier');

// Relay 2 inside signal house.
await teleport(29, 8);
await shot('signal-interior');
await pressE();
await page.waitForTimeout(250);
for (let i = 0; i < 2; i++) await page.locator('#tone-row [data-slot="0"]').click();
for (let i = 0; i < 4; i++) await page.locator('#tone-row [data-slot="2"]').click();
await page.locator('#puzzle-submit').click();
await page.waitForTimeout(500);
s = await page.evaluate(() => ({ obj: window.__dbg.objectiveIndex, chapter: document.querySelector('#chapter-label').textContent, solved: [...window.__dbg.solved] }));
console.log('relay2', s);

// Spire.
await teleport(28, -39.5);
await pressE();
await page.waitForTimeout(400);
await shot('spire-exterior');
await teleport(28, -47);
await shot('spire-interior');
await teleport(28, -53.5);
await pressE();
await page.waitForTimeout(250);
await page.locator('#tone-row [data-slot="0"]').click();
await page.locator('#tone-row [data-slot="3"]').click();
await page.locator('#puzzle-submit').click();
await page.waitForTimeout(500);
s = await page.evaluate(() => ({ obj: window.__dbg.objectiveIndex, solved: [...window.__dbg.solved] }));
console.log('relay3', s);

// Gate and ending.
await teleport(0, -62);
await pressE();
await page.waitForTimeout(500);
await teleport(0, -80);
await page.waitForTimeout(900);
const ending = await page.evaluate(() => !document.querySelector('#ending-screen').classList.contains('hidden'));
console.log('ending', ending);
await shot('ending');

// Cat petting and bird flight.
await page.evaluate(() => location.reload());
await page.waitForTimeout(1800);
await page.locator('#start-button').click();
await page.waitForTimeout(900);
const catInfo = await page.evaluate(() => { const c = window.__dbg.cats[0]; return { x: c.group.position.x, z: c.group.position.z, name: c.entity.name }; });
await teleport(catInfo.x + 1.1, catInfo.z);
await page.waitForTimeout(500);
await shot('cat-close');
const petBefore = await page.evaluate(() => ({ near: window.__dbg.nearby?.type, pet: window.__dbg.cats[0].petTimer }));
await pressE();
await page.waitForTimeout(900);
const petAfter = await page.evaluate(() => ({ pet: window.__dbg.cats[0].petTimer, count: window.__dbg.cats[0].petCount, toast: document.querySelector('#toast-text').textContent }));
console.log('cat', { catInfo, petBefore, petAfter });
await shot('cat-petting');

const birdInfo = await page.evaluate(() => { const b = window.__dbg.birds[0]; return { x: b.group.position.x, z: b.group.position.z, state: b.state }; });
await teleport(birdInfo.x + 1.5, birdInfo.z + 1.5);
await page.waitForTimeout(500);
const birdAfter = await page.evaluate(() => ({ state: window.__dbg.birds[0].state, y: window.__dbg.birds[0].group.position.y, wings: window.__dbg.birds[0].wings.length }));
console.log('bird', { birdInfo, birdAfter });
await shot('bird-flight');

console.log('errors', errors);
await browser.close();

