import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
page.on('pageerror', e => console.log('PAGEERROR', e.message));
await page.goto('http://localhost:3002/', { waitUntil: 'load' });
await page.waitForTimeout(1400);
await page.locator('#start-button').click();
await page.waitForTimeout(4200);
async function shot(name){await page.waitForTimeout(250);await page.screenshot({path:`/tmp/opencode/${name}.png`});}
async function freeze(name, px,py,pz, tx,ty,tz){
  await page.evaluate(([px,py,pz,tx,ty,tz])=>{
    window.__freezeCamera=true;
    window.__dbg.camera.position.set(px,py,pz);
    window.__dbg.camera.lookAt(tx,ty,tz);
  },[px,py,pz,tx,ty,tz]);
  await shot(name);
  await page.evaluate(()=>{window.__freezeCamera=false});
}
// Player close-up in open street.
await page.evaluate(()=>window.__dbg.teleport(0,20));
await page.waitForTimeout(1200);
await freeze('player-close',2.2,1.7,23.4,0,1.1,20);
// NPC close-up: Dara, face her toward the camera.
const npc = await page.evaluate(()=>{
  const e=window.__dbg.entities.find(x=>x.name==='DARA');
  e.group.rotation.y=0;
  return [e.group.position.x,e.group.position.z];
});
await freeze('npc-dara',npc[0],1.55,npc[1]+2.7,npc[0],1.25,npc[1]);
// Cat close-up.
const cat = await page.evaluate(()=>{const c=window.__dbg.cats[0];return [c.group.position.x,c.group.position.z];});
await page.evaluate(()=>{const c=window.__dbg.cats[0];c.group.rotation.y=0;});
await freeze('cat-close3',cat[0]+.1,1.0,cat[1]+1.9,cat[0],.45,cat[1]);
// Bird close-up, before it flees.
const bird = await page.evaluate(()=>{const b=window.__dbg.birds[0];return [b.group.position.x,b.group.position.z];});
await page.evaluate(()=>{const b=window.__dbg.birds[0];b.group.rotation.y=0;});
await freeze('bird-close3',bird[0],.95,bird[1]+1.9,bird[0],.55,bird[1]);
// Interior shots with dissolved walls.
for (const [name,x,z] of [['archive2',-27,7],['market2',-51,30],['police2',-51,50],['post2',51,30],['house2',51,52],['signal2',29,5],['spire2',28,-50]]){
  await page.evaluate(([x,z])=>window.__dbg.teleport(x,z),[x,z]);
  await page.waitForTimeout(2200);
  await shot(name);
}
await browser.close();

