import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
const errors = [];
page.on('pageerror', e => errors.push('PAGEERROR: ' + e.message));
page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE: ' + m.text()); });
await page.goto('http://localhost:3002/', { waitUntil: 'load', timeout: 45000 });
await page.waitForTimeout(1600);
await page.locator('#start-button').click();
await page.waitForTimeout(1200);

const st = () => page.evaluate(() => ({
  obj: window.__dbg.objectiveIndex,
  pass: window.__dbg.pass,
  solved: [...window.__dbg.solved],
  near: window.__dbg.nearby ? window.__dbg.nearby.type + ':' + window.__dbg.nearby.name : null,
  puzzleOpen: !document.querySelector('#puzzle-screen').classList.contains('hidden'),
  dialogueOpen: !document.querySelector('#dialogue-screen').classList.contains('hidden'),
  chapter: document.querySelector('#chapter-label').textContent,
  title: document.querySelector('#mission-title').textContent,
  pos: [Math.round(window.__dbg.player.position.x), Math.round(window.__dbg.player.position.z)]
}));
const tp = async (x, z) => { await page.evaluate(([x, z]) => window.__dbg.teleport(x, z), [x, z]); await page.waitForTimeout(450); };
const interact = async () => { await page.evaluate(() => window.__dbg.interact()); await page.waitForTimeout(250); };
const openPuzzle = async ent => { await page.evaluate(e => window.__dbg.openPuzzle(window.__dbg[e]), ent); await page.waitForTimeout(250); };
const click = async (slot, n) => { for (let i = 0; i < n; i++) await page.locator(`#tone-row [data-slot="${slot}"]`).click(); };

// 1. Archive.
await tp(-27, 10); console.log('archive near', await st());
await openPuzzle('archive');
await click(0, 2); await click(1, 1); await click(2, 4);
await page.locator('#puzzle-submit').click(); await page.waitForTimeout(500);
console.log('archive solved', await st());

// 2. Relay 01.
await tp(-12, 41); console.log('relay1 near', await st());
await interact(); console.log('relay1 opened', await st());
await click(0, 1); await click(1, 3); await click(2, 4);
await page.locator('#puzzle-submit').click(); await page.waitForTimeout(600);
console.log('relay1 solved', await st());

// 3. Checkpoint.
await tp(4.8, 10.2); await interact(); await page.waitForTimeout(400);
console.log('checkpoint', await st());

// 4. Signal House / Relay 02.
await tp(22, 3); await page.waitForTimeout(600);
await page.screenshot({ path: '/tmp/opencode/final-signal.png' });
await tp(29, 3);
await interact(); console.log('relay2 opened', await st());
await click(0, 2); await click(2, 4);
await page.locator('#puzzle-submit').click(); await page.waitForTimeout(600);
console.log('relay2 solved', await st());

// 5. Spire door + Relay 03.
await tp(28, -40); await interact(); await page.waitForTimeout(400);
console.log('spire door', await st());
await tp(28, -53.5);
await interact(); console.log('relay3 opened', await st());
await click(0, 1); await click(3, 1);
await page.locator('#puzzle-submit').click(); await page.waitForTimeout(600);
console.log('relay3 solved', await st());
await page.screenshot({ path: '/tmp/opencode/final-spire.png' });

// 6. Gate and ending.
await tp(0, -62);
await interact(); await page.waitForTimeout(700);
console.log('gate', await st());
await tp(0, -80); await page.waitForTimeout(1100);
const ending = await page.evaluate(() => !document.querySelector('#ending-screen').classList.contains('hidden'));
console.log('ending visible', ending);
await page.screenshot({ path: '/tmp/opencode/final-ending.png' });

// 7. Dialogue test on a fresh load.
await page.evaluate(() => location.reload());
await page.waitForTimeout(1800);
await page.locator('#start-button').click();
await page.waitForTimeout(1000);
await tp(-13, 22);
const beforeTalk = await st();
await interact();
const openedTalk = await st();
const lines = [];
for (let i = 0; i < 3; i++) { await page.locator('#dialogue-next').click(); await page.waitForTimeout(200); lines.push(await page.locator('#dialogue-text').textContent()); }
const afterTalk = await st();
console.log('dialogue', { beforeTalk, openedTalk, lines: lines.map(l => l.slice(0, 30)), afterTalk });
await page.screenshot({ path: '/tmp/opencode/final-dialogue.png' });

