const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true, deviceScaleFactor: 2 });
const errors = [];
page.on('pageerror', e => errors.push('PAGEERROR: ' + e.message));
page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE: ' + m.text()); });
await page.goto('http://localhost:3002/', { waitUntil: 'domcontentloaded', timeout: 60000 });
await page.waitForTimeout(4000);
console.log('boot', await page.evaluate(() => ({ mobile: document.body.classList.contains('mobile'), map: !!document.querySelector('#map-panel'), touch: !!document.querySelector('#interact-touch'), start: !!document.querySelector('#start-button') })));
await page.screenshot({ path: '/tmp/opencode/final-mobile-start.png' });
await page.locator('#start-button').click();
await page.waitForTimeout(4000);
await page.screenshot({ path: '/tmp/opencode/final-mobile.png' });
console.log('running', await page.evaluate(() => ({
  title: document.querySelector('#mission-title').textContent,
  mapRect: document.querySelector('#map-panel').getBoundingClientRect().toJSON(),
  missionRect: document.querySelector('#mission-card').getBoundingClientRect().toJSON(),
  vw: innerWidth, vh: innerHeight
})));
console.log('errors', errors);
await browser.close();

