import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
const errors = [];
page.on('pageerror', e => errors.push('PAGEERROR: ' + e.message));
page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE: ' + m.text()); });
await page.goto('http://localhost:3002/', { waitUntil: 'load', timeout: 45000 });
await page.waitForTimeout(1600);
await page.screenshot({ path: '/tmp/opencode/v2-intro.png' });
await page.locator('#start-button').click();
await page.waitForTimeout(1500);
const tp = async (x, z) => { await page.evaluate(([x, z]) => window.__dbg.teleport(x, z), [x, z]); await page.waitForTimeout(500); };
const st = () => page.evaluate(() => ({ obj: window.__dbg.objectiveIndex, pass: window.__dbg.pass, solved: [...window.__dbg.solved], near: window.__dbg.nearby ? window.__dbg.nearby.name : null, chapter: document.querySelector('#chapter-label').textContent, title: document.querySelector('#mission-title').textContent, pos: [+window.__dbg.player.position.x.toFixed(1), +window.__dbg.player.position.z.toFixed(1)] }));
const interactAndPuzzle = async (target) => {
  await page.waitForFunction(n => window.__dbg.nearby?.name === n, target, { timeout: 12000 });
  await page.evaluate(() => window.__dbg.interact());
  await page.waitForTimeout(400);
};

// Chapter 1: archive.
await tp(-24, 14);
await page.screenshot({ path: '/tmp/opencode/v2-archive-inside.png' });
await interactAndPuzzle('TRANSIT ARCHIVE');
console.log('archive opened', await st());
for (let i = 0; i < 2; i++) await page.locator('#tone-row [data-slot="0"]').click();
await page.locator('#tone-row [data-slot="1"]').click();
for (let i = 0; i < 4; i++) await page.locator('#tone-row [data-slot="2"]').click();
await page.locator('#puzzle-submit').click(); await page.waitForTimeout(600);
console.log('archive solved', await st());

// Relay 1.
await tp(-12, 41);
await interactAndPuzzle('RELAY 01');
await page.locator('#tone-row [data-slot="0"]').click();
for (let i = 0; i < 3; i++) await page.locator('#tone-row [data-slot="1"]').click();
for (let i = 0; i < 4; i++) await page.locator('#tone-row [data-slot="2"]').click();
await page.locator('#puzzle-submit').click(); await page.waitForTimeout(700);
console.log('relay1', await st());
await page.screenshot({ path: '/tmp/opencode/v2-chapter2.png' });

// Checkpoint.
await tp(4.8, 10.2);
await interactAndPuzzle('MERIDIAN CHECK');
console.log('checkpoint', await st());

// Relay 2.
await tp(29, 3);
await interactAndPuzzle('RELAY 02');
for (let i = 0; i < 2; i++) await page.locator('#tone-row [data-slot="0"]').click();
for (let i = 0; i < 4; i++) await page.locator('#tone-row [data-slot="2"]').click();
await page.locator('#puzzle-submit').click(); await page.waitForTimeout(700);
console.log('relay2', await st());

// Spire + relay 3.
await tp(28, -40);
await interactAndPuzzle('SPIRE ACCESS');
console.log('spire', await st());
await tp(28, -53.5);
await interactAndPuzzle('RELAY 03');
await page.locator('#tone-row [data-slot="0"]').click();
await page.locator('#tone-row [data-slot="3"]').click();
await page.locator('#puzzle-submit').click(); await page.waitForTimeout(700);
console.log('relay3', await st());
await page.screenshot({ path: '/tmp/opencode/v2-spire.png' });

// Gate + ending.
await tp(0, -62);
await interactAndPuzzle('PERIMETER GATE');
await page.waitForTimeout(600);
console.log('gate', await st());
await tp(0, -80); await page.waitForTimeout(1600);
console.log('ending', await page.evaluate(() => !document.querySelector('#ending-screen').classList.contains('hidden')));
await page.screenshot({ path: '/tmp/opencode/v2-ending.png' });
console.log('errors', errors);
await browser.close();

