import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
const errors = [];
page.on('pageerror', e => errors.push('PAGEERROR: ' + e.message));
page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE: ' + m.text()); });
await page.goto('http://localhost:3002/', { waitUntil: 'load' });
await page.waitForTimeout(1600);
await page.locator('#start-button').click();
await page.waitForTimeout(1200);
async function tp(x, z) { await page.evaluate(([x, z]) => window.__dbg.teleport(x, z), [x, z]); await page.waitForTimeout(600); }
async function roomShot(name, x, z, yaw = 0) {
  await tp(x, z);
  await page.evaluate(([x, z, yaw]) => {
    const c = window.__dbg.camera;
    window.__freezeCamera = true;
    c.position.set(x + Math.sin(yaw) * 4.7, 3.05, z + Math.cos(yaw) * 4.7);
    c.lookAt(x, 1.95, z);
  }, [x, z, yaw]);
  await page.waitForTimeout(500);
  await page.screenshot({ path: `/tmp/opencode/v4-${name}.png` });
  await page.evaluate(() => { window.__freezeCamera = false; });
}
// Street / exterior.
await page.evaluate(() => { window.__freezeCamera = true; window.__dbg.camera.position.set(-7, 4.2, 14); window.__dbg.camera.lookAt(-24, 2.4, 14); });
await page.waitForTimeout(500);
await page.screenshot({ path: '/tmp/opencode/v4-archive-street.png' });
await page.evaluate(() => { window.__freezeCamera = false; });
await page.evaluate(() => { window.__freezeCamera = true; window.__dbg.camera.position.set(0, 8, 22); window.__dbg.camera.lookAt(-24, 3, 30); });
await page.waitForTimeout(500);
await page.screenshot({ path: '/tmp/opencode/v4-low-street.png' });
await page.evaluate(() => { window.__freezeCamera = false; });

await roomShot('archive', -24, 14);
await roomShot('market', -51, 30, Math.PI / 2);
await roomShot('signal', 29, 5);
await roomShot('house', 51, 52);
await roomShot('spire', 28, -50);
await roomShot('post', 51, 30);
await roomShot('police', -51, 50);

// Player close-up.
await tp(0, 20);
await page.evaluate(() => {
  const c = window.__dbg.camera;
  window.__freezeCamera = true;
  c.position.set(1.9, 1.75, 22.6);
  c.lookAt(0, 1.15, 20);
});
await page.waitForTimeout(400);
await page.screenshot({ path: '/tmp/opencode/v4-player.png' });
await page.evaluate(() => { window.__freezeCamera = false; });

// Cat close-up.
const cat = await page.evaluate(() => { const c = window.__dbg.cats[0]; return [c.group.position.x, c.group.position.z]; });
await page.evaluate(() => { window.__dbg.cats[0].group.rotation.y = 0; });
await page.evaluate(([x, z]) => {
  const c = window.__dbg.camera;
  window.__freezeCamera = true;
  c.position.set(x + 0.1, 1.0, z + 1.9);
  c.lookAt(x, 0.45, z);
}, cat);
await page.waitForTimeout(400);
await page.screenshot({ path: '/tmp/opencode/v4-cat.png' });
await page.evaluate(() => { window.__freezeCamera = false; });

// Bird close-up.
const bird = await page.evaluate(() => { const b = window.__dbg.birds[0]; return [b.group.position.x, b.group.position.z]; });
await page.evaluate(() => { window.__dbg.birds[0].group.rotation.y = 0; });
await page.evaluate(([x, z]) => {
  const c = window.__dbg.camera;
  window.__freezeCamera = true;
  c.position.set(x, 0.95, z + 1.9);
  c.lookAt(x, 0.55, z);
}, bird);
await page.waitForTimeout(400);
await page.screenshot({ path: '/tmp/opencode/v4-bird.png' });
await page.evaluate(() => { window.__freezeCamera = false; });

console.log('errors', errors);
await browser.close();

