import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
const errors = [];
page.on('pageerror', e => errors.push('PAGEERROR: ' + e.message));
page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE: ' + m.text()); });
await page.goto('http://localhost:3002/', { waitUntil: 'load' });
await page.waitForTimeout(1600);
await page.locator('#start-button').click();
await page.waitForTimeout(1200);
async function tp(x, z) { await page.evaluate(([x, z]) => window.__dbg.teleport(x, z), [x, z]); await page.waitForTimeout(600); }
async function cam(px, py, pz, tx, ty, tz, name) {
  await page.evaluate(([px, py, pz, tx, ty, tz]) => {
    window.__freezeCamera = true;
    window.__dbg.camera.position.set(px, py, pz);
    window.__dbg.camera.lookAt(tx, ty, tz);
  }, [px, py, pz, tx, ty, tz]);
  await page.waitForTimeout(500);
  await page.screenshot({ path: `/tmp/opencode/v5-${name}.png` });
  await page.evaluate(() => { window.__freezeCamera = false; });
}
// Player front.
await tp(0, 20);
await cam(2.4, 1.65, 22.4, 0, 1.05, 20, 'player-front');
// Cat: move player away, set cat still and face +z.
await tp(40, 40);
const cat = await page.evaluate(() => {
  const c = window.__dbg.cats[0];
  c.group.position.set(-18, 0, 12); c.group.rotation.y = 0;
  return [-18, 12];
});
await cam(cat[0], 0.9, cat[1] + 2.6, cat[0], 0.42, cat[1], 'cat-front');
console.log('cat box', await page.evaluate(() => {
  const b = new window.__dbg.cats[0].group.constructor(); return null;
}).catch(() => 'n/a'));
// Bird: park it on the ground away from the player.
const bird = await page.evaluate(() => {
  const b = window.__dbg.birds[0];
  b.state = 'ground'; b.group.position.set(-2, 0, 44); b.group.rotation.x = 0; b.group.rotation.y = 0; b.home = { x: -2, z: 44 };
  return [-2, 44];
});
await tp(40, 40);
await cam(bird[0], 0.9, bird[1] + 2.4, bird[0], 0.45, bird[1], 'bird-front');
await cam(bird[0] + 1.6, 0.85, bird[1] + 1.6, bird[0], 0.45, bird[1], 'bird-side');
// Archive room.
await tp(-24, 14);
await cam(-24, 3.05, 18.7, -24, 1.9, 14, 'archive-room');
// Low street.
await cam(-2, 7, 26, -22, 3, 32, 'low-street');
console.log('errors', errors);
await browser.close();

content.text:
The bird is **way too big**! In both screenshots, the bird is about the size of the player (or bigger) and stands upright in the middle of the road like a giant penguin. The camera is 2.4 units away, but the bird fills a huge portion. The bird's body is at y=.62 with scale (.2,.2,.34) → 0.4m wide. At 2.4m it should be small. Yet it appears ~1.8m tall. 

Why? The bird group might be scaled by something. Wait, the bird in the screenshots stands ~2m tall relative to the road markings. The camera is at y=.9, 2.4m away, looking down at y=.45. The road markings behind show the scale: the lane dashes are ~3m long; the bird spans about... hmm, hard to tell. The bird is in the foreground (2.4m away), so it appears large due to perspective compared to the road. Its head is at the center of the screen and its feet at the bottom. The bird's actual height: legs .28, body .62, head .79+.16=.95 → ~1m tall. The player is 1.9m. So the bird is 1m tall, which is a *large* bird (like a penguin) but not player-sized. In the screenshot at 2.4m, it appears big because it's close. If I move the camera to 5m, it would look smaller. But a 1m-tall bird in the city is too big for a crow/pigeon. Real crows are ~0.4m. The user wants a bird that flaps, pecks trash, and flees; the bird should be smaller, maybe 0.5m tall. Let's scale the bird group by 0.62, making it ~0.6m tall. The cat is ~0.7m, so the bird at 0.6 is fine.

More importantly, the bird's **wings** look like two black ovals stuck to the sides (in the side view) and the **head** is a black ball with no visible eyes/beak from this angle? In the front view, I see a light-gray face/beak area (the white thing under the head) and two white things at the sides (the wings?) — the bird looks like a penguin with a black body, a gray chest, and orange legs. The head is a black sphere with no visible eyes from the front because the eyes are at z=.143 on the head, but the head is at z=.24 relative to the body? The camera is in front, so the eyes should be visible. The face appears as a light-gray/white egg shape (the "chest" is at z=.23, color #485257, and the beak is a brown cone). Hmm, the front view shows the bird's back? Wait, the bird group rotation.y=0 faces +z. The camera is at z+2.4 looking -z, so it sees the front (+z). The head is at z=.24, eyes at head z=.143 → world z=.383. The beak at head z=.18 → .42. The chest at .23. The white/gray oval at the center-top is the "chest" (color #485257) which is at z=.23 but *below* the head, and the head is the black ball above it. The eyes are probably hidden behind the head's curvature or too small/dark to see. The beak (brown) is tiny and points forward at the bottom of the head, maybe hidden by the chest.

The bird's **tail** is not visible from the front (expected) but in the side view I see a black mass extending back? The side view shows the bird's side, but the wings are folded flat. The tail isn't obvious.

The bird is a mess visually. I need to rebuild it more clearly:
- Scale down to ~0.6 tall.
- Give it a **distinct head** above the body, with a clear lighter face patch, large white eyes with black pupils, and a bright orange/yellow beak pointing forward.
- Give it **folded wings** on the sides with visible feather tips, and a **tail** extending back.
- Legs thin, orange.
- Body color dark gray/black with a lighter belly.
- Make the head bigger relative to the body (cartoon bird) so the eyes/beak are readable.
- For flying, the wings should spread; the current wing pivots work, but the wing shape is a flattened sphere. Make the wing a simple elongated shape.

Let me rebuild `makeBird` from scratch with a clearer design:

```
function makeBird(x,z,color='#2b3337',accent='#4a565a'){
