  const face=new THREE.Mesh(eyeGeo,bellyM);face.scale.set(.13,.12,.06);face.position.set(0,-.005,.135);head.add(face);
  // eyes
  for(const side of [-1,1]){
    const w=new THREE.Mesh(eyeGeo,white);w.position.set(side*.075,.045,.135);w.scale.set(.045,.05,.028);head.add(w);
    const p=new THREE.Mesh(eyeGeo,black);p.position.set(side*.075,.045,.158);p.scale.set(.022,.03,.012);head.add(p);
