function makeBird(x,z,color='#262e32',accent='#39454a'){
  const g=new THREE.Group();g.position.set(x,0,z);world.add(g);
  const bodyM=toon(color),wingM=toon(accent),beakM=toon('#c88a3c'),legM=toon('#7a5131'),white=toon('#f4f0dc'),black=toon('#0f1416');
  const body=new THREE.Mesh(eyeGeo,bodyM);body.scale.set(.2,.2,.34);body.position.y=.62;g.add(body);
  const chest=new THREE.Mesh(eyeGeo,toon('#485257'));chest.scale.set(.14,.16,.18);chest.position.set(0,.58,.23);g.add(chest);
  const tail=new THREE.Group();tail.position.set(0,.62,-.38);g.add(tail);
  for(const i of [-1,0,1]){const f=new THREE.Mesh(eyeGeo,wingM);f.scale.set(.06,.023,.22);f.position.set(i*.065,0,-.06);f.rotation.y=i*.24;f.rotation.x=.12;tail.add(f)}
  const wings=[];
  for(const side of [-1,1]){
    const pivot=new THREE.Group();pivot.position.set(side*.17,.67,-.02);pivot.rotation.z=side*.12;g.add(pivot);
    const wing=new THREE.Mesh(eyeGeo,wingM);wing.scale.set(.05,.115,.29);wing.position.set(side*.03,-.03,-.04);pivot.add(wing);
    for(let i=0;i<3;i++){const feather=new THREE.Mesh(eyeGeo,wingM);feather.scale.set(.035,.02,.1);feather.position.set(side*.02,-.09,-.13-i*.07);pivot.add(feather)}
    wings.push({pivot,side});
  }
  const head=new THREE.Group();head.position.set(0,.79,.24);g.add(head);
  const skull=new THREE.Mesh(eyeGeo,bodyM);skull.scale.set(.155,.16,.16);head.add(skull);
  for(const side of [-1,1]){
    const w=new THREE.Mesh(eyeGeo,white);w.position.set(side*.105,.03,.12);w.scale.set(.04,.045,.025);head.add(w);
    const p=new THREE.Mesh(eyeGeo,black);p.position.set(side*.108,.03,.143);p.scale.set(.019,.023,.01);head.add(p);
  }
  cone(head,0,-.01,.18,.05,.17,beakM,Math.PI/2);
  for(const side of [-1,1]){cylinder(g,side*.07,.29,.02,.018,.018,.28,legM,5);box(g,side*.07,.15,.06,.08,.02,.11,legM,false)}
  const a={group:g,head,wings,tail,state:'ground',home:{x,z},phase:rand()*6,heading:rand()*6.28,peck:0,walkT:rand()*3,flyT:0,vel:new THREE.Vector3(),x,z};
  birds.push(a);return a;
}

