import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
const errors = [];
page.on('pageerror', e => errors.push('PAGEERROR: ' + e.message));
page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE: ' + m.text()); });
await page.goto('http://localhost:3002/', { waitUntil: 'load' });
await page.waitForTimeout(1600);
await page.locator('#start-button').click();
await page.waitForTimeout(5200);
async function tp(x, z) { await page.evaluate(([x, z]) => window.__dbg.teleport(x, z), [x, z]); await page.waitForTimeout(700); }
async function cam(px, py, pz, tx, ty, tz, name) {
  await page.evaluate(([px, py, pz, tx, ty, tz]) => {
    window.__freezeCamera = true;
    window.__dbg.camera.position.set(px, py, pz);
    window.__dbg.camera.lookAt(tx, ty, tz);
  }, [px, py, pz, tx, ty, tz]);
  await page.waitForTimeout(500);
  await page.screenshot({ path: `/tmp/opencode/v6-${name}.png` });
  await page.evaluate(() => { window.__freezeCamera = false; });
}
await tp(0, 20);
