function interiorDetail(b,{papers=22,theme='low'}={}){
  const {x,z,w,d,h}=b;
  const minX=x-w/2+1, maxX=x+w/2-1, minZ=z-d/2+1, maxZ=z+d/2-1;
  // false ceiling trusses
  for(let i=0;i<4;i++){
    const zz=z-d/2+2+i*(d-4)/3;
    box(world,x,h-.28,zz,w-.9,.1,.1,mats.dark,false);
  }
  // hanging cable loops
  for(let i=0;i<7;i++){
    const ax=minX+rand()*(maxX-minX), az=minZ+rand()*(maxZ-minZ);
    const len=.5+rand()*1.6;
    box(world,ax,h-.45-len/2,az,.028,len,.028,mats.dark,false);
  }
  // wall pipes
  for(const side of [-1,1]){
    for(let i=0;i<2;i++){
      const px=x+side*(w/2-.55), pz=minZ+.8+i*(d-2)/2;
      cylinder(world,px,h*.48,pz,.045,.045,h*.8,mats.rust,6);
    }
  }
  // paper litter
  for(let i=0;i<papers;i++){
    const px=minX+rand()*(maxX-minX), pz=minZ+rand()*(maxZ-minZ);
    const p=box(world,px,.075,pz,.14+rand()*.18,.008,.1+rand()*.14, i%4===0?mats.lit:mats.ivory,false);
    p.rotation.y=rand()*Math.PI;
  }
  // little floor debris (bottles/cans)
  for(let i=0;i<6;i++){
    const px=minX+rand()*(maxX-minX), pz=minZ+rand()*(maxZ-minZ);
    const cn=cylinder(world,px,.11,pz,.06,.06,.17,i%2?mats.orange:mats.concrete,8);
    cn.rotation.z=Math.PI/2.2*Math.round(rand()); // some tipped
  }
  // stacked crates near corners
  const corners=[[minX+.8,minZ+.8],[maxX-.8,minZ+.8],[minX+.8,maxZ-.8],[maxX-.8,maxZ-.8]];
  for(const [cx,cz] of corners){
    if(b.doorSide==='+x'&&cx>maxX-2.1)continue;
    if(b.doorSide==='-x'&&cx<minX+2.1)continue;
    if(b.doorSide==='+z'&&cz>maxZ-2.1)continue;
